          isReplacedTag(c) ||
          isCheckboxLike(c) ||
          isPill(c) ||
          isDecorativeLeaf(c) ||
          isBadgeGrid(c) ||
          isIconGlyph(c) ||
          needsVisualEffectScreenshot(c)
